const body = $input.first().json;
const { meta, pieces, cles, observations } = body;

const ROOM_LABELS = {
  entree:'Entrée', salon:'Salon / Séjour', cuisine:'Cuisine',
  wc_communs:'WC communs', buanderie:'Buanderie',
  chambre_1:'Chambre 1', chambre_2:'Chambre 2', chambre_3:'Chambre 3',
  chambre_4:'Chambre 4', chambre_5:'Chambre 5',
  salle_eau_12:"Salle d'eau (ch. 1 & 2)", salle_bain_34:'Salle de bain (ch. 3 & 4)',
  salle_eau_privee_5:"Salle d'eau privée (ch. 5)",
  wc_partages_12:'WC partagés (ch. 1 & 2)', wc_partages_34:'WC partagés (ch. 3 & 4)',
  wc_prives_5:'WC privés (ch. 5)'
};
const ETAT_LABELS = { TB:'Très Bon', B:'Bon', P:'Passable', M:'Mauvais', 'N/A':'N/A' };
const ETAT_COLORS = { TB:'#2E7D32', B:'#66BB6A', P:'#FFA726', M:'#EF5350', 'N/A':'#BDBDBD' };
const ELEM_LABELS = {
  sol:'Sol', murs:'Murs', plafond:'Plafond', fenetres:'Fenêtres', porte_s:'Porte(s)',
  eclairage:'Éclairage', prises_interrupteurs:'Prises/Interrupteurs',
  projecteur:'Projecteur', ecran:'Écran', enceinte:'Enceinte',
  plaques:'Plaques', four:'Four', hotte:'Hotte', refrigerateur:'Réfrigérateur',
  congelateur:'Congélateur', lave_vaisselle:'Lave-vaisselle', evier:'Évier',
  machine_1:'Machine 1', machine_2:'Machine 2', seche_linge:'Sèche-linge'
};

function esc(s) {
  return String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}
function unslug(k) { return ELEM_LABELS[k] || (k.charAt(0).toUpperCase() + k.slice(1).replace(/_/g,' ')); }

const typeLabel = meta.type === 'entree' ? "d'entrée" : "de sortie";
const d = new Date(meta.date + 'T12:00:00');
const dateFormatted = d.toLocaleDateString('fr-FR', { day:'2-digit', month:'long', year:'numeric' });

let roomsHtml = '';
for (const [roomId, room] of Object.entries(pieces || {})) {
  const label = ROOM_LABELS[roomId] || unslug(roomId);
  let rows = '';
  for (const [k, v] of Object.entries(room.elements || {})) {
    const color = ETAT_COLORS[v.etat] || '#666';
    rows += `<tr>
      <td style="padding:5px 8px;border-bottom:1px solid #eee;font-size:13px">${esc(unslug(k))}</td>
      <td style="padding:5px 8px;border-bottom:1px solid #eee;font-size:13px;color:${color};font-weight:600">${esc(ETAT_LABELS[v.etat] || v.etat || '—')}</td>
      <td style="padding:5px 8px;border-bottom:1px solid #eee;font-size:12px;color:#555">${esc(v.commentaire || '')}</td>
    </tr>`;
  }
  const photosNote = (room.photoUrls && room.photoUrls.length > 0)
    ? `<p style="font-size:11px;color:#888;margin:3px 0 10px;font-style:italic">${room.photoUrls.length} photo(s) disponible(s) dans le dossier Drive</p>` : '';
  roomsHtml += `<div style="margin-bottom:18px">
    <div style="background:#4A7C59;color:#fff;padding:6px 12px;border-radius:4px 4px 0 0;font-size:13px;font-weight:700">${esc(label)}</div>
    <table style="width:100%;border-collapse:collapse;border:1px solid #ddd;border-top:none">
      <thead><tr style="background:#f5f3f0">
        <th style="padding:5px 8px;text-align:left;font-size:11px;color:#888">ÉLÉMENT</th>
        <th style="padding:5px 8px;text-align:left;font-size:11px;color:#888">ÉTAT</th>
        <th style="padding:5px 8px;text-align:left;font-size:11px;color:#888">COMMENTAIRE</th>
      </tr></thead>
      <tbody>${rows}</tbody>
    </table>${photosNote}
  </div>`;
}

const obsHtml = observations
  ? `<div style="background:#fff8e1;padding:12px 16px;border-radius:6px;margin-bottom:20px;border-left:4px solid #FFA726"><strong>Observations générales :</strong><br><span style="font-size:13px">${esc(observations)}</span></div>`
  : '';

const templateName = `EDL ${meta.type === 'entree' ? 'Entrée' : 'Sortie'} — Ch.${meta.chambre} — ${meta.locataire} — ${meta.date}`;

const html = `<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"></head>
<body style="font-family:Arial,sans-serif;max-width:780px;margin:0 auto;padding:20px;color:#333">
  <div style="border-bottom:3px solid #4A7C59;padding-bottom:10px;margin-bottom:18px">
    <h1 style="color:#345A3E;margin:0 0 3px;font-size:20px">État des lieux ${esc(typeLabel)}</h1>
    <p style="color:#666;margin:0;font-size:12px">rue Marie Duboccage, Rouen</p>
  </div>
  <table style="width:100%;background:#f5f3f0;border-radius:6px;padding:10px;margin-bottom:18px;font-size:13px"><tr>
    <td style="padding:3px 10px"><span style="color:#888;font-size:10px;font-weight:600">LOCATAIRE</span><br>${esc(meta.locataire)}</td>
    <td style="padding:3px 10px"><span style="color:#888;font-size:10px;font-weight:600">CHAMBRE</span><br>${meta.chambre}</td>
    <td style="padding:3px 10px"><span style="color:#888;font-size:10px;font-weight:600">DATE</span><br>${esc(dateFormatted)}</td>
    <td style="padding:3px 10px"><span style="color:#888;font-size:10px;font-weight:600">CLÉS REMISES</span><br>${cles}</td>
  </tr></table>
  ${roomsHtml}
  ${obsHtml}
  <hr style="margin:24px 0;border:none;border-top:2px solid #eee">
  <h2 style="color:#345A3E;font-size:15px;margin-bottom:6px">Remarques et signature du locataire</h2>
  <p style="color:#666;font-size:12px;margin-bottom:14px">Lisez attentivement cet état des lieux. Indiquez vos éventuelles réserves avant de signer.</p>
  <p style="font-size:13px;font-weight:600;margin-bottom:4px">Remarques (optionnel) :</p>
  <textarea name="Remarques" role="Locataire" required="false" style="width:100%;height:90px;font-size:13px;padding:8px;border:1px solid #ccc;border-radius:4px;box-sizing:border-box"></textarea>
  <br><br>
  <p style="font-size:13px;font-weight:600;margin-bottom:6px">Signature :</p>
  <signature-field name="Signature" role="Locataire" required="true" style="display:block;width:260px;height:75px"></signature-field>
  <p style="font-size:10px;color:#bbb;margin-top:24px">Document généré le ${new Date().toLocaleDateString('fr-FR')} — ${esc(templateName)}</p>
</body></html>`;

return [{ json: { ...body, html, templateName } }];

const tpl = $input.first().json;
const originalData = $('Code - Build HTML').first().json;
const templateId = tpl.id;
if (!templateId) throw new Error('DocuSeal template creation failed: ' + JSON.stringify(tpl));
return [{ json: { ...originalData, docusealTemplateId: templateId } }];

const d = $input.first().json;
const prenom = (d.meta.locataire || '').split(' ')[0];
const typeLabel = d.meta.type === 'entree' ? "d'entrée" : "de sortie";
const submissionBody = {
  template_id: d.docusealTemplateId,
  send_email: true,
  message: {
    subject: `État des lieux ${typeLabel} — ${d.meta.locataire} — Signature requise`,
    body: `Bonjour ${prenom},\n\nVotre état des lieux ${typeLabel} pour la chambre ${d.meta.chambre} (${d.meta.date}) est disponible pour signature.\n\nMerci de le relire attentivement, ajouter vos éventuelles remarques, et le signer via le bouton ci-dessous.\n\nCordialement,\nCamille`
  },
  submitters: [{
    email: d.meta.locataireEmail,
    role: 'Locataire',
    name: d.meta.locataire
  }]
};
return [{ json: submissionBody }];

